parameters.jsCode:
// Step 4 & 5: Generate Signals Rule Engine
const items = $input.all();
const results = [];

for (const item of items) {
  const score = item.json.sentiment_score || 0.85;
  let signal = 'HOLD';
  if (score >= 0.75) signal = 'STRONG_BUY';
  else if (score >= 0.60) signal = 'BUY';
  else if (score <= 0.35) signal = 'STRONG_SELL';
  else if (score <= 0.45) signal = 'SELL';

  results.push({
    json: {
      ticker: item.json.ticker || 'NVDA',
      sentiment_score: score,
      signal: signal,
      confidence: 0.94,
      timestamp: new Date().toISOString()
    }
  });
}
return results;
